-- 대전시 시민추천 빵집 90곳 추가 (출처: daejeon.go.kr/fod BreadRecommendList, 좌표: 카카오 장소·주소 검색)
-- 카카오에서 이름으로만 찾은 곳은 주소가 시청 자료와 달라 카카오 주소(현재 정보)를 씀


-- 기존 매장 중 시민추천 목록에도 있는 곳
update public.bakeries set tags = array_append(tags, '시민추천') where slug in ('jeongdong-munhwasa', 'cold-butter-bakeshop', 'planet-egg-tart', 'harupang', 'green-bakery', 'coudebien', 'eco-bread-house', 'orange-blossom', 'boboro-bakery', 'mongsim-hannam') and not ('시민추천' = any(tags));
